import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Scalable Policy Evaluation with Video World Models","description":"","frontmatter":{"title":"Scalable Policy Evaluation with Video World Models","arxiv":"2511.11520","date":"2025-11-14","authors":"Wei-Cheng Tseng, Jinwei Gu, Qinsheng Zhang, Hanzi Mao, Ming-Yu Liu, Florian Shkurti, Yen-Chen Lin","categories":"cs.RO","topics":"物理感知视频生成, 策略评测, 动作条件世界模型","outline":[2,2]},"headers":[],"relativePath":"papers/2511.11520.md","filePath":"papers/2511.11520.md","lastUpdated":null}'),l={name:"papers/2511.11520.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="scalable-policy-evaluation-with-video-world-models" tabindex="-1">Scalable Policy Evaluation with Video World Models <a class="header-anchor" href="#scalable-policy-evaluation-with-video-world-models" aria-label="Permalink to &quot;Scalable Policy Evaluation with Video World Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.11520" target="_blank" rel="noreferrer">2511.11520</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-14</td></tr><tr><td><strong>作者</strong></td><td>Wei-Cheng Tseng, Jinwei Gu, Qinsheng Zhang, Hanzi Mao, Ming-Yu Liu, Florian Shkurti, Yen-Chen Lin</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用 Fourier 特征把机器人动作编码进时间嵌入，把预训练视频扩散模型改造成动作条件世界模型，让策略在里面自回归 rollout，再由 VLM 判定成败，从而无需真机就能给策略排序。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 上 v1 提交于 2025-11-14，本文基于最新的 <strong>v3</strong>（2025-12-04 修订）全文撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>通才机器人操作策略现在能听懂自然语言、跨任务跨本体工作，但评测跟不上。真机测试是金标准，代价是昂贵的数据采集与标注、大量机器人基础设施、可复现性差，还要频繁复位环境，把未验证的策略部署到实体机器人上本身也有安全风险。手工搭仿真环境没有解决这个问题，原因是工程量巨大，而且物理和渲染两侧的 sim-to-real gap 都很大。</p><p>论文问的是：能不能用动作条件的视频生成模型当世界模型，来做可扩展的策略评测？注意这里的目标被刻意放低了——不是要预测策略的绝对成功率，而是要在多个策略之间给出可靠的相对排序与相关性。这个降级很关键，因为排序对系统性偏差有一定容忍度，而绝对值没有。价值在于：如果排序可信，策略迭代的内循环就能完全脱离真机，只在最后做一次真机确认。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>动作条件视频预测模型这条线已经有若干工作，在娱乐（GameGen、Genie、GameNGen）、规划、强化学习方向都有探索。作者归纳出这类方法相对已有评测手段的四条优势：相比真机测试可复现且不需要昂贵硬件；相比手工仿真直接从真实数据学习，能捕捉复杂的视觉与动力学属性；直接以真实观测为条件，天然完成 real-to-sim；性能随数据与模型规模增长，不需要人力去新增任务。</p><p>策略评测侧的直接对手有三个。SIMPLER 构造物理仿真器来逼近真实环境，证明了用真实数据训练的策略可以在仿真里估计其真实表现，但依赖大量域随机化来弥合 gap，且需要人工整理 3D 资产与精细的环境设计。AutoEval 做的是在真实世界里自动评测通才策略，仍然面临电机过热、墙钟时间长的问题，而且真机评测本身有噪声与波动。WorldEval 也提出用视频模型做策略评测，但它要求视频模型使用动作解码器的特征作为条件信号——这意味着换一个新策略就要重新对接，限制了适用范围。</p><p>这一条对比很重要：本文的技术选择（动作直接编码进时间嵌入，与策略架构完全解耦）正是为了绕开 WorldEval 的这个限制。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个约束出发：配对的视频-动作数据在机器人操作里非常贵，规模远小于互联网视频。如果从零训练一个动作条件的视频模型，只能用这些配对数据，物理先验学不出来。所以必须复用在互联网视频上预训练过的模型。</p><p>但预训练视频模型不接受动作条件。怎么改造？最省事、对原模型扰动最小的做法是找一个已经贯穿全网络的低维条件通路，把动作挂上去。扩散模型里正好有这样一条通路：时间步嵌入。动作是低维连续量（末端执行器位姿），直接过 MLP 会让网络难以学到高频依赖，因此先做 Fourier 特征映射再进 MLP——这是 NeRF 时代就验证过的技巧。这个 MLP 的 FLOPs 相对整网可以忽略，训练与推理效率不受影响。</p><p>第二个问题是训练数据的分布。人类遥操作演示几乎全是成功轨迹，而评测时策略会产生各种失败与奇怪动作，模型在这些动作上是 OOD 的。解决办法很自然：把不同质量的策略在环境里 rollout 出来的轨迹也加进训练集，让模型见过失败长什么样。</p><p>第三个问题是怎么判定成败。人工判定就回到了成本问题，于是用现成 VLM 抽帧判断。这一步是整套自动化的最后一环，也是后面被证明最脆弱的一环。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>评测策略不需要一个物理正确的模拟器，只需要一个排序保序的模拟器。既然如此，就不必去手工建模物理，而可以借用互联网视频预训练出的先验：把动作接到扩散模型的时间嵌入上，让它变成一个能被动作驱动的环境；再喂给它一批好坏参差的策略 rollout，让它见过失败长什么样。剩下的判定交给 VLM。整条链路里没有一处需要真机或 3D 资产。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>目标形式化。</strong> 设有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个策略，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 的真实累积表现为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>（真机 rollout 估计的平均成功率）。目标是构造世界模拟器 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>，使得仿真中的相对表现 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 与真实相对表现强相关。</p><p><strong>模型。</strong> backbone 是开源的 Cosmos-Predict2-Video2World-2B，一个带额外 cross-attention 层的 Diffusion Transformer，2B 可训练参数，已在大规模文生视频与图生视频数据上预训练。动作定义为世界坐标系下机械臂末端执行器位姿。原始动作先过 Fourier 特征映射，再过 MLP 得到动作嵌入，加到时间嵌入上，从而使整个视频扩散模型成为动作条件的。全框架用 EDM 目标端到端训练，设置沿用 Cosmos。</p><p><strong>数据增广。</strong> 训练数据以人类遥操作演示为主，但演示轨迹的动作分布窄且几乎全是成功案例。作者用不同表现水平的策略在环境里 rollout，把这些轨迹并入训练集，从 0.3M 扩到 1.1M transitions。</p><p><strong>评测流程。</strong> 三步：把策略接入视频模型，以初始帧与动作序列为条件自回归生成 rollout 视频；抽帧连同任务完成的定义 prompt 一起送进 VLM 判定成败；计算预测表现与真实表现之间的相关性。以 RoboMimic 的 Can 任务为例：初始帧是可乐罐在大料箱里，策略每步输出末端位姿，视频模型逐段生成后续画面，直到 rollout 结束；VLM 看到罐子最终落在小目标箱内则判成功。多个策略各跑若干次，得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，与它们在真实 Robosuite 环境里的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 比对。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>动力学的学习目标。</strong> 设观测空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span></span></span></span>、动作空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span></span></span></span>。每一步策略 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> 接收历史观测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 输出动作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，环境给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>。要学的是环境动力学</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>这个形式是任务无关的：多个任务共享同一个观测空间（视频帧），因此同一个模型可以吃多任务数据并从知识迁移中获益。反复从该预测模型采样、每次以自己上一步生成的观测为条件，就模拟出完整的交互轨迹。</p><p><strong>排序违反度量。</strong> 评测指标沿用 SIMPLER 的 MMRV 与 Pearson 相关系数。两个策略之间的排序违反定义为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">RankViolation</span></span><span class="mopen">(</span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord mathbf">1</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">]</span></span></span></span></span></span></p><p>指示函数在「仿真给出的相对顺序与真实相反」时为 1，前面的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span> 是罚项权重：把两个真实表现相差很大的策略排反，比把两个几乎一样好的策略排反严重得多。这个设计让指标对无关紧要的错排宽容，对实质性错排敏感。</p><p>聚合方式取每个策略的最坏情况再平均：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">MMRV</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3557em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">≤</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">≤</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">RankViolation</span></span><span class="mopen">(</span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span></span></span></span></span></p><p>取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mop">max</span></span></span></span> 而非平均，意味着一个策略只要被严重错排一次就会被完整计入，因此 MMRV 是一个保守指标，越低越好。Pearson 系数则度量预测值与真实值的线性一致性，越高越好，两者互补：Pearson 高但 MMRV 也高，说明整体趋势对但存在个别严重错排。</p><p><strong>动作嵌入。</strong> 原始动作先做 Fourier 特征映射再过 MLP。Fourier 映射的作用是把低维输入升到高频基上，让 MLP 有能力表达输入的高频函数——末端位姿的微小变化需要对应画面的明确差异，直接用低维输入会被网络平滑掉。这个 MLP 的 FLOPs 远小于网络其余部分，因此不影响训练与推理效率。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：在动力学已知为真值的受控环境里，视频模型能否正确排序策略？</strong> 用 RoboMimic 的四个任务（Lift 最简单；Can 需要更稳的抓取与精确放置；Square 需要精确对准把方形螺母套到杆上；Tool Hang 最复杂，多阶段、需要旋转与精细插入）。策略是 diffusion policy 的 CNN 与 transformer 版本，用不同训练步数造出不同质量的策略，每个策略吃两路图像（夹爪视角与全局视角）的最近两帧、预测未来八步动作。结果是 Pearson 分别为 0.879 / 0.860 / 0.847 / 0.833，MMRV 分别为 0.015 / 0.141 / 0.165 / 0.217。趋势清楚：任务时程越长，相关性越弱、错排越严重，Tool Hang 的 MMRV 0.217 已经是相当大的排序误差。</p><p><strong>问题二：加入策略 rollout 数据有多重要？</strong> 去掉这部分数据后，Pearson 掉到 0.856 / 0.744 / 0.505 / 0.502，MMRV 升到 0.222 / 0.226 / 0.384 / 0.288——在 Square 与 Tool Hang 上几乎失去评测能力。视频预测质量侧同样退化：在分布内 PSNR 从 20.622 掉到 18.712、FVD 从 98.455 升到 130.211；分布外 PSNR 从 15.996 掉到 14.931、FVD 从 250.234 升到 285.001。定性上，没有 rollout 数据训练的模型会出现夹爪逐渐消失这类伪影。作者还测了 rollout 数量的影响，更多 rollout 一致地提升评测精度，且在更难的 Square 上效果比在 Lift 上更明显。</p><p><strong>问题三：预训练权重有多重要？</strong> 从零训练的模型 Pearson 掉到 0.822 / 0.716 / 0.523 / 0.645，分布内 PSNR 17.731、分布外 PSNR 14.754、分布外 FVD 291.158，均差于预训练版本。定性上，从零训练的模型在夹爪与物体接触、或物体互相碰撞时更容易出现幻觉、形变与遮挡错误。作者的解释是预训练提供了从演示数据里学不到的物理动力学先验。</p><p><strong>问题四：换 backbone 会怎样？</strong> 对比 Cosmos-Predict-1-7B（0.845 / 0.750 / 0.606 / 0.500）、Cosmos-Predict-1-14B（0.800 / 0.716 / 0.511 / 0.666）、Wan-2.1-14B-LoRA（0.842 / 0.746 / 0.801 / 0.789）、IRASim（0.835 / 0.780 / 0.213 / 0.642）。两个值得注意的现象：Cosmos-Predict-1 的 14B 版本并不优于 7B 版本，说明单纯放大参数量不带来评测能力提升；完全从零训练的 IRASim 表现最差，在 Square 上 Pearson 仅 0.213。作者把 Cosmos-Predict2 的优势归因于其预训练数据与 physical-AI 域高度对齐。</p><p><strong>问题五：能否迁移到真实环境与通才策略？</strong> 沿用 SIMPLER 的设定，在 Bridge 上评测 OCTO-Small、OCTO-Base、OpenVLA，任务为举起锅、胡萝卜、茄子、杯子。视频模型用 Bridge V2 训练，另外采集 300 条自有环境的轨迹以对齐布置差异。结论是预测表现与真实表现呈正相关（论文以图给出，未列具体系数）。</p><p><strong>问题六：失败模式是什么？</strong> 作者列了四类。幻觉：方形螺母的把手会凭空消失导致策略必然失败；茄子会被幻觉进夹爪里，这会高估策略表现。多视角不一致：全局视角显示罐子已被抓住，夹爪视角里却没有，作者归因于训练时缺少显式的视角一致性损失。复制预测：夹爪位移很小时扩散模型倾向于直接复制条件图像，导致环境静止、策略无法推进，这在 Tool Hang 上尤其常见，因为插入动作本身位移极小。VLM 标注误差：自动判定的准确率只有 65% 到 80%。所有这些误差都会在自回归生成中累积，Tool Hang 每条 rollout 涉及 700 步 transition，小误差会迅速放大。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版：</strong> 论文把预训练视频扩散模型 Cosmos-Predict2-Video2World-2B 改造成动作条件世界模型，方式是把末端位姿经 Fourier 特征与 MLP 编码后加到时间嵌入上，与策略架构完全解耦。策略在这个模型里自回归 rollout，由 VLM 判定成败，用 SIMPLER 的 MMRV 与 Pearson 度量与真实表现的一致性。在 RoboMimic 四任务上 Pearson 达到 0.833 到 0.879，但 MMRV 随任务时程变长从 0.015 升至 0.217。两个消融显示成败关键：去掉策略 rollout 增广数据后 Square 与 Tool Hang 的 Pearson 跌到 0.5 附近，去掉预训练权重同样大幅退化，而单纯把 backbone 从 7B 换到 14B 反而变差。四类失败模式——幻觉、多视角不一致、复制预测、VLM 标注仅 65% 到 80% 准确——在自回归下会累积，Tool Hang 每条 rollout 达 700 步。</p><p><strong>3 句话版：</strong> 要用视频模型评策略，动作条件必须与策略解耦（挂在时间嵌入上），训练数据必须包含失败轨迹，权重必须来自与物理域对齐的预训练。做到这三点，短时程任务的排序基本可信，长时程任务不可信。整套评测的上限被 VLM 判定器的 65% 到 80% 准确率压住。</p><p><strong>1 句话版：</strong> 动作条件视频模型可以当廉价的策略排序器，前提是任务够短、训练数据见过失败、且接受判定器本身的噪声。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：视频模型的预测误差对不同策略是无偏的，因此排序能够在误差中幸存。整篇论文的主张是相对的（排序与相关性），这个降级本身很聪明，但只有当误差不与策略质量相关时才成立。</p><p>有明确理由怀疑它不成立。论文自己举的例子是模型会「把茄子幻觉进夹爪里」，并指出这会高估策略表现。关键在于这种幻觉不是随机发生的——扩散模型的先验倾向于补全「符合任务语义的画面」，因此当一个策略把夹爪移动到物体附近、动作大体正确却差之毫厘时，先验最容易把它补成成功；而一个动作完全跑偏的策略不会触发这种补全。也就是说幻觉系统性地偏袒「接近成功」的中等策略，压缩了它们与真正好策略之间的差距。同理，「复制预测」在位移小的时候触发，而精细操作策略正是位移小的那一类，这会系统性地惩罚做精细动作的策略。两种偏差都与策略行为相关，不是白噪声。</p><p>论文提供的间接证据恰好指向这个方向：MMRV 随任务复杂度单调上升（0.015、0.141、0.165、0.217），而复杂任务正是精细位移与近似成功状态最多的场合。缺的证据是误差的策略条件分解——把每个策略的仿真成功率减去真机成功率，看这个偏差是否与策略的真实水平相关。只要报告这一张图，读者就能判断偏差是平移（不影响排序）还是压缩/翻转（破坏排序）。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要重训视频模型的验证：把 VLM 判定器这一环单独隔离出来测。论文自承其准确率只有 65% 到 80%，但没有分析这个噪声如何传播到最终的 Pearson 与 MMRV。</p><p>做法分两步。第一步是实测：在 RoboMimic 的 Lift 与 Square 上，取真实仿真器 rollout 的视频（有 ground-truth 成败标签），用与论文相同的抽帧与 prompt 设置跑 VLM，得到混淆矩阵，尤其是假阳率与假阴率是否对称。第二步是蒙特卡洛传播：假设真实成功率已知的 10 个策略，按实测的假阳/假阴率对每次 rollout 的判定结果加噪，重复 1000 次，统计 Pearson 与 MMRV 的分布。</p><p>判据：如果在 70% 判定准确率下，MMRV 的标准差就达到 0.1 量级，那么论文报告的 Tool Hang 上 0.217 与去掉预训练后 0.363 之间的差异有相当一部分可能来自判定噪声而非模型质量，多组消融的结论需要重新审视；如果 MMRV 的分布很窄，说明多次 rollout 的平均已经把判定噪声压下去了，那么论文的比较是稳的。这个实验只需要 VLM API 与已有的仿真 rollout。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出一个更简单的替代解释：0.83 到 0.88 的 Pearson 可能根本不需要视频模型。RoboMimic 上的策略池是用「不同训练步数」造出来的，这意味着策略质量与训练步数强单调相关，而训练步数与很多不需要世界模型就能测的量（动作分布与专家动作的距离、动作序列的平滑度、策略在演示集上的验证损失）同样强相关。如果这些零成本代理量与真实成功率的 Pearson 也在 0.8 以上，那么视频模型的全部价值就存疑。</p><p>具体设计：在同一批 RoboMimic 策略上计算三个基线——策略在留出演示集上的 behavior-cloning 验证损失；策略动作与最近邻专家动作的平均 L2 距离；策略动作序列的抖动度。分别与真实成功率算 Pearson 与 MMRV，与论文的表 I 直接对比。如果任何一个基线在 Lift 与 Can 上打平甚至超过 0.86，那么视频模型只在 Square 与 Tool Hang 这类长时程任务上才有独立价值——而恰恰在这两个任务上它的 MMRV 最差。这会把论文的结论倒过来：视频模型在它有优势的地方最不可靠。</p><p>另一类可预测失败：把策略池换成「不同架构、训练充分」而非「同架构、不同步数」。此时策略之间的差异不再沿着单一的质量轴排列，代理量失效，视频模型是否仍能排序就成了真正的考验。论文的真机部分用了 OCTO-Small、OCTO-Base、OpenVLA 三个不同模型，方向是对的，但只有三个点、且只给了定性的正相关，样本量不足以支撑结论。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动这个想法的局限是：整套评测把视频模型当成一个不透明的黑箱环境，模型自己不知道什么时候在编造。幻觉、多视角不一致、复制预测三类失败都是静默的——它们不会报错，只会污染成败判定，而且如上所述污染方向可能与策略质量相关。</p><p>一个非增量的重构是把评测从「单点 rollout 计成功率」换成「带弃权的可靠性感知评测」。相邻领域可借的工具是选择性预测与共形预测（conformal prediction）：给世界模型配一个不确定性估计，在每一步用多次采样的分歧度、或多视角之间的一致性残差作为置信信号；一旦置信度低于阈值，这条 rollout 被标记为「模型不知道」，从统计中剔除而不是当作成功或失败计入。共形预测能进一步把「剔除比例」与「剩余估计的覆盖率」联系起来，给出可证明的误差界——这正是当前评测最缺的东西：论文能给出 Pearson，但给不出「这个排序有多大概率是对的」。</p><p>第一个实验很小：在 RoboMimic 的 Square 任务上，对每条 rollout 的每一步用同一动作采样 4 条候选未来，计算它们在潜空间的方差作为置信信号。然后画一条弃权率与 MMRV 的曲线：随着弃权率从 0 升到 30%，剩余 rollout 上的 MMRV 是否单调下降。如果 MMRV 能从 0.165 降到 0.05 以下，说明不确定性信号确实定位到了不可信的 rollout，这条路成立，并且给出了一个实用的旋钮——用户可以按需要在覆盖率与可靠性之间取舍；如果 MMRV 不随弃权率下降，说明模型的错误是自信的错误，那么需要的不是不确定性估计而是显式的一致性约束（比如训练时加入多视角一致性损失），这也是论文自己在失败分析里点到但没有实施的方向。</p>',61)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
